// T3 / recent-route-fragment. Region event runs on connected clients; only one active primary GM handles award.
const __itemKey = "recent-route-fragment";
const __itemName = "Recent Route Fragment";
const __guidance = "Confirm the character explicitly chooses to secure the route fragment from the survey desk. Leave it there on refusal or cancellation.";
const __primary = game.users.filter(u => u.active && u.isGM).sort((a,b) => a.id.localeCompare(b.id))[0];
if (!__primary || game.user?.id !== __primary.id || !game.user?.isGM) return;
const __token = event?.data?.token ?? event?.token ?? null;
const __actor = __token?.actor ?? null;
if (!__token || !__actor || !__actor.uuid) return;
const __kernel = game.macros.get("FHQiFYx6OntZVo9d");
const __ledger = game.journal.get("xhlXv6CCH34HVga3");
const __canonical = game.items.filter(i => i.getFlag?.("world","dicebox")?.stableId === "dbx:central-lodge:item:" + __itemKey);
if (!__kernel || !__ledger || __canonical.length !== 1) {
  console.error("[CL-33] Missing exact canonical dependency for " + __itemKey);
  return;
}
const __state = __ledger.getFlag("world","dicebox")?.state;
if (!__state || !__state.items || !__state.items[__itemKey]) return;
if (__state.items[__itemKey].recovered === true) return;
const __id = __token.uuid + ":" + __itemKey;
const __root = globalThis.__diceboxCl33PickupGuards ??= {pending:new Set(),cancelledUntil:new Map()};
if (__root.pending.has(__id) || Date.now() < (__root.cancelledUntil.get(__id) ?? 0)) return;
__root.pending.add(__id);
try {
  const __accepted = await foundry.applications.api.DialogV2.confirm({
    window:{title:__itemName + " — GM Recovery Authorization"},
    content:"<p><strong>GM checkpoint:</strong> "+__guidance+"</p><p>Confirm only if the player has explicitly chosen to recover this item. Otherwise leave it available for a later directed search or return visit.</p>",
    modal:true,
    rejectClose:false,
    yes:{label:"Confirm Player Takes Item"},
    no:{label:"Leave Item"}
  });
  if (!__accepted) {
    __root.cancelledUntil.set(__id, Date.now() + 20000);
    return;
  }
  const __fresh = __ledger.getFlag("world","dicebox")?.state;
  if (!__fresh?.items?.[__itemKey] || __fresh.items[__itemKey].recovered === true) return;
  const __result = await __kernel.execute({
    actor:__actor,
    token:__token,
    event,
    speaker:{dicebox:{
      contract:"dicebox-region-behavior/v1", action:"pickup", trigger:"TOKEN_ENTER",
      itemKey:__itemKey, progressionCritical:true,
      message:"<p>You recover the <strong>"+__itemName+"</strong> and secure it for later use.</p>"
    }}
  });
