  if (canvas?.interface?.createScrollingText) await canvas.interface.createScrollingText(center, text, { duration: 4500, jitter: 0.12 });
  else ui.notifications.info(text);
  return;
}
let noticed = Boolean(foundry.utils.getProperty(token, base + ".noticed"));
