if (!rolled) {
  const roll = await (new Roll("1d20")).evaluate();
  const total = Number(roll.total ?? 0);
  noticed = total >= 8;
  await token.update({
    [base + ".noticeRolled"]: true,
    [base + ".noticeTotal"]: total,
    [base + ".noticed"]: noticed
  });
  if (!noticed) return;
}
if (!noticed) return;
const center = token.object?.center ?? { x: token.x, y: token.y };
const foundText = "A brittle folded scrap is wedged into a narrow seam in the stone. The surviving marks repeat at measured intervals. Suggested check: Investigation or Religion.";
