  rejectClose: false,
  yes: { label: "Recover the scrap" },
  no: { label: "Leave it in place" }
});
if (!recover) return;
try {
  await actor.update({ [recoveryPath]: true });
  const text = "You work the brittle scrap free without destroying it and secure it for later comparison.";
  if (canvas?.interface?.createScrollingText) await canvas.interface.createScrollingText(center, text, { duration: 6000, jitter: 0.12 });
  else ui.notifications.info(text);
} catch (error) {
  ui.notifications.warn("The scrap remains recoverable; its state could not be recorded. A GM can resolve the recovery without losing the clue.");
}

const token = event?.data?.token ?? null;
if (!token) return;
if (game.user?.id !== event?.user?.id) return;
const path = "flags.world.dicebox.t3.terminusSeen";
if (foundry.utils.getProperty(token, path)) return;
await token.update({ [path]: true });
const text = "The estate rails stop at the abandoned terminus. Beyond them, the older worked passage continues on foot. Dust lies thick on the sleepers, but a narrow strip of stone beside them has been disturbed more recently.";
const center = token.object?.center ?? { x: token.x, y: token.y };
if (canvas?.interface?.createScrollingText) await canvas.interface.createScrollingText(center, text, { duration: 8000, jitter: 0.12 });
else ui.notifications.info(text);

