if (dbx.f1.innerWardResolved === true) return;

if (dbx.f1.cicadaInstalled !== true) {
  await ChatMessage.create({
    content: `<p>The repeated stone divisions are inert. Nothing answers the cadence of footsteps here.</p>`,
    whisper: recipients
  });
  return;
}

