if (now - Number(dbx.f1.lastWardPromptAt ?? 0) < 5000) return;
dbx.f1.lastWardPromptAt = now;
await scene.setFlag("world", "dicebox", dbx);

const confirmed = await foundry.applications.api.DialogV2.confirm({
  window: {title: "F1 — Inner Ward"},
  content: `<p>The completed Cicada is seated. The inner ward is now listening.</p><p>Have the players correctly performed the Measure / Ritual Rhythm established by the prior clues?</p><p>This BUILD intentionally does not invent a sequence that is not present in the campaign source. Confirm only when you adjudicate the performed rhythm as correct.</p>`,
  yes: {label: "Correct Measure"},
  no: {label: "Not Yet"},
  modal: true
});
if (!confirmed) {
  await ChatMessage.create({
    content: `<p>The stone carries the attempted cadence forward, then returns it altered. The inner threshold remains sealed.</p>`,
    whisper: recipients
  });
  return;
}

