reread.f1 ??= {};
reread.f1.innerWardResolved = true;
reread.f1.innerWardResolvedAt = Date.now();
reread.f1.innerWardResolvedBy = game.user.id;
await scene.setFlag("world", "dicebox", reread);

const gate = Array.from(scene.walls ?? []).find(w => w.getFlag("world","dicebox")?.stableId === "dbx:central-lodge:f1:wall:inner-gate");
if (gate) await scene.updateEmbeddedDocuments("Wall", [{_id: gate.id, ds: CONST.WALL_DOOR_STATES.OPEN}]);

const lights = Array.from(scene.lights ?? []).filter(l => ["ward","threshold"].includes(l.getFlag("world","dicebox")?.group));
if (lights.length) await scene.updateEmbeddedDocuments("AmbientLight", lights.map(l => ({_id: l.id, hidden: false})));

await ChatMessage.create({
  content: `<p>The final interval lands cleanly. The ward answers in the same measure, then falls silent as the sealed stone gives way.</p>`,
  whisper: recipients
});

const activeGMs = game.users.filter(u => u.active && u.isGM).sort((a,b) => a.id.localeCompare(b.id));
if (!activeGMs.length || game.user.id !== activeGMs[0].id) return;
