if (!scene || !token?.actor) return;

const dbx = foundry.utils.deepClone(scene.getFlag("world", "dicebox") ?? {});
dbx.f1 ??= {};
if (dbx.f1.cicadaInstalled === true) return;

const actors = [];
for (const u of game.users) {
  if (!u.isGM && u.character && !actors.some(a => a.id === u.character.id)) actors.push(u.character);
}
if (!actors.some(a => a.id === token.actor.id)) actors.push(token.actor);

const inventory = [];
for (const a of actors) {
  for (const item of a.items ?? []) {
    const flags = item.getFlag?.("world", "dicebox") ?? {};
    const stableId = flags.canonicalStableId ?? flags.stableId ?? null;
    inventory.push({actor:a, item, stableId});
  }
}
const findPart = key => inventory.find(x => x.stableId === "dbx:central-lodge:item:" + key);
const parts = {
  body: findPart("infernal-cicada-body"),
  wingI: findPart("cicada-wing-i"),
  wingII: findPart("cicada-wing-ii"),
  wingIII: findPart("cicada-wing-iii"),
  wingIV: findPart("cicada-wing-iv")
};
const missing = Object.entries(parts).filter(([,v]) => !v).map(([k]) => k);

const recipients = [...new Set([event?.user?.id, ...activeGMs.map(u => u.id)].filter(Boolean))];
if (missing.length) {
  await ChatMessage.create({
    content: `<p>The shallow receiving recess does not answer. Its divisions suggest that several separate fitted pieces belong here, but the assembly is incomplete.</p>`,
    whisper: recipients
  });
  return;
}

const holders = Object.values(parts).map(p => `${p.item.name} — ${p.actor.name}`);
const confirmed = await foundry.applications.api.DialogV2.confirm({
