if (!token?.actor) return;
const actor = token.actor;
const state = foundry.utils.deepClone(actor.getFlag("world","dicebox") ?? {});
state.centralLodge ??= {};
state.centralLodge.f1 ??= {};
if (state.centralLodge.f1.resonanceObserved === true) return;
