  content: `<p>The recesses, pillars, and cut channels repeat at deliberate intervals. Walking between them produces a faint sequence of returning vibrations, closer to measured cadence than decoration.</p>`,
  whisper: recipients
});

const activeGMs = game.users
  .filter(u => u.active && u.isGM)
  .sort((a,b) => a.id.localeCompare(b.id));

if (
  !activeGMs.length ||
  game.user.id !== activeGMs[0].id
) return;

const token = event?.data?.token;
const sourceScene =
  event?.region?.parent ?? canvas?.scene;

if (!token?.actor || !sourceScene) return;

const dbx =
  foundry.utils.deepClone(
    sourceScene.getFlag("world", "dicebox") ?? {}
  );

if (dbx.f1?.innerWardResolved !== true) {
  return;
}

const destination =
  await fromUuid("Scene.HWitOe1wSid7MZ1y.Region.pplHOCmUZOqFymOy");

if (
  !destination ||
  destination.documentName !== "Region"
) {
  console.error(
    "[DiceBox F1→F2] Destination Region unavailable.",
    "Scene.HWitOe1wSid7MZ1y.Region.pplHOCmUZOqFymOy"
  );
  return;
}

const destinationScene =
  destination.parent;

let user =
  game.users.get(event?.user?.id) ?? null;

if (!user || user.isGM) {
  user =
    game.users.find(
      u =>
        u.active &&
        !u.isGM &&
        u.character?.id === token.actor.id
    ) ?? null;
